"use client"

import { useState, useEffect } from "react"
import { useNavigate, useLocation } from "react-router-dom"
import {
  Home,
  LogOut,
  User,
  ChevronLeft,
  ChevronRight,
  Menu,
  ChevronDown,
  Users,
  Building2,
  ClipboardList,
  FileText,
  ChefHat,
  GraduationCap,
  UserCog,
  Package,
} from "lucide-react"

export default function Sidebar({ isCollapsed, setIsCollapsed, closeMenu }) {
  const navigate = useNavigate()
  const location = useLocation()
  const [isMobile, setIsMobile] = useState(false)
  const [isAdminOpen, setIsAdminOpen] = useState(false)
  const [isAbsenceOpen, setIsAbsenceOpen] = useState(false)
  const [isReportsOpen, setIsReportsOpen] = useState(false)

  useEffect(() => {
    const checkIfMobile = () => {
      setIsMobile(window.innerWidth < 768)
      if (window.innerWidth < 768) {
        setIsCollapsed(true)
      }
    }

    checkIfMobile()
    window.addEventListener("resize", checkIfMobile)
    return () => window.removeEventListener("resize", checkIfMobile)
  }, [setIsCollapsed])

  useEffect(() => {
    const adminRoutes = ["/Suppliers", "/Deputydirectors", "/Chefs"]
    if (adminRoutes.includes(location.pathname)) {
      setIsAdminOpen(true)
    }
  }, [location.pathname])

  useEffect(() => {
    const absenceRoutes = ["/AbsenceRequests"]
    if (absenceRoutes.includes(location.pathname)) {
      setIsAbsenceOpen(true)
    }
  }, [location.pathname])

  useEffect(() => {
    const reportRoutes = ["/reports/chef", "/reports/intern", "/reports/deputydirector"]
    if (reportRoutes.includes(location.pathname)) {
      setIsReportsOpen(true)
    }
  }, [location.pathname])

  const handleLogout = () => {
    localStorage.removeItem("token")
    navigate("/")
  }

  const AdministrationItems = [
    { title: "Fournisseurs", icon: Users, href: "/Suppliers" },
    { title: "Gestionnaire d'hôtel", icon: Users, href: "/Deputydirectors" },
    { title: "Cuisinier", icon: Users, href: "/Chefs" },
    { title: "Stagiaires", icon: GraduationCap, href: "/InternsPourSuperadmin" },
    { title: "anciens stagiaires", icon: GraduationCap, href: "/FormerInternsSuperadmin" },
    { title: "Suivi des paiements", icon: ClipboardList, href: "/PaymentTrackingPourSuperadmin" },
    { title: "Gérer les produits", icon: Package, href: "/ManageProductsPourSuperadmin" },
  ]

  const ReportItems = [
    { title: "Rapports des Cuisinier", icon: ChefHat, href: "/ChefReports" },
    { title: "Rapports des Stagiaires", icon: GraduationCap, href: "/InternReports" },
    { title: "Rapports des Gestionnaires d'hôtel", icon: UserCog, href: "/DirectorReports" },
  ]

  const navItems = [{ title: "Tableau de bord", icon: Home, href: "/dashboard" }]
  const bottomNavItems = [{ title: "Compte", icon: User, href: "/AccountSuperadmin" }]

  const toggleSidebar = () => {
    setIsCollapsed(!isCollapsed)
    if (closeMenu) closeMenu()
  }

  const toggleAdminSection = () => {
    setIsAdminOpen(!isAdminOpen)
    if (isCollapsed) setIsCollapsed(false)
  }

  const toggleAbsenceSection = () => {
    setIsAbsenceOpen(!isAbsenceOpen)
    if (isCollapsed) setIsCollapsed(false)
  }

  const toggleReportsSection = () => {
    setIsReportsOpen(!isReportsOpen)
    if (isCollapsed) setIsCollapsed(false)
  }

  return (
    <>
      <div
        className={`fixed inset-y-0 left-0 z-50 flex flex-col mt-[56px] bg-[#F5F6FA] border-r border-[#C8A45D]/30 transition-all duration-300 ease-in-out shadow-lg ${
          isCollapsed ? "w-16" : "w-64"
        }`}
      >
        <button
          onClick={toggleSidebar}
          className="absolute -right-3 top-20 bg-white border border-[#C8A45D]/30 rounded-full p-1.5 shadow-md z-10 hidden md:flex hover:bg-[#C8A45D]/20 transition-colors"
        >
          {isCollapsed ? (
            <ChevronRight size={16} className="text-[#00717F]" />
          ) : (
            <ChevronLeft size={16} className="text-[#00717F]" />
          )}
        </button>

        <div className="flex flex-col h-full">
          <div className="p-2">
            <button
              onClick={toggleSidebar}
              className="md:hidden w-full flex items-center justify-center p-2 rounded-md text-[#00717F] hover:bg-[#C8A45D]/20 transition-colors"
            >
              <Menu size={20} />
            </button>
          </div>

          <nav className="flex-1 overflow-y-auto px-2 py-2">
            <ul className="space-y-1">
              {navItems.map((item) => {
                const isActive = location.pathname === item.href
                return (
                  <li key={item.title}>
                    <button
                      onClick={() => navigate(item.href)}
                      className={`flex items-center w-full rounded-md px-3 py-2.5 text-sm font-medium transition-all ${
                        isActive
                          ? "bg-[#C8A45D]/20 text-[#00717F] shadow-sm"
                          : "text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F]"
                      }`}
                    >
                      <item.icon
                        className={`h-5 w-5 ${
                          isActive ? "text-[#00717F]" : "text-[#333333] group-hover:text-[#00717F]"
                        }`}
                      />
                      {!isCollapsed && (
                        <span className="ml-3 truncate transition-opacity duration-200">{item.title}</span>
                      )}
                    </button>
                  </li>
                )
              })}

              {/* Administration Section */}
              <li className="mt-4">
                <button
                  onClick={toggleAdminSection}
                  className={`flex items-center justify-between w-full rounded-md px-3 py-2.5 text-sm font-medium transition-all ${
                    isAdminOpen
                      ? "bg-[#00717F] text-white shadow-sm"
                      : "text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F]"
                  }`}
                >
                  <div className="flex items-center">
                    <Building2 className={`h-5 w-5 ${isAdminOpen ? "text-white" : "text-[#333333]"}`} />
                    {!isCollapsed && (
                      <span className="ml-3 truncate transition-opacity duration-200">Administration</span>
                    )}
                  </div>
                  {!isCollapsed && (
                    <ChevronDown
                      className={`h-4 w-4 transition-transform duration-200 ${
                        isAdminOpen ? "rotate-180 text-white" : "text-[#333333]"
                      }`}
                    />
                  )}
                </button>
                {isAdminOpen && (
                  <ul className={`mt-1 space-y-1 ${isCollapsed ? "pl-0" : "pl-4"}`}>
                    {AdministrationItems.map((item) => {
                      const isActive = location.pathname === item.href
                      return (
                        <li key={item.title}>
                          <button
                            onClick={() => navigate(item.href)}
                            className={`flex items-center w-full rounded-md px-3 py-2.5 text-sm font-medium transition-all ${
                              isActive
                                ? "bg-[#C8A45D]/20 text-[#00717F] shadow-sm"
                                : "text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F]"
                            }`}
                          >
                            <item.icon className={`h-5 w-5 ${isActive ? "text-[#00717F]" : "text-[#333333]"}`} />
                            {!isCollapsed && (
                              <span className="ml-3 truncate transition-opacity duration-200">{item.title}</span>
                            )}
                          </button>
                        </li>
                      )
                    })}
                  </ul>
                )}
              </li>

              {/* Reports Section */}
              <li className="mt-4">
                <button
                  onClick={toggleReportsSection}
                  className={`flex items-center justify-between w-full rounded-md px-3 py-2.5 text-sm font-medium transition-all ${
                    isReportsOpen
                      ? "bg-[#00717F] text-white shadow-sm"
                      : "text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F]"
                  }`}
                >
                  <div className="flex items-center">
                    <FileText className={`h-5 w-5 ${isReportsOpen ? "text-white" : "text-[#333333]"}`} />
                    {!isCollapsed && <span className="ml-3 truncate transition-opacity duration-200">Rapports</span>}
                  </div>
                  {!isCollapsed && (
                    <ChevronDown
                      className={`h-4 w-4 transition-transform duration-200 ${
                        isReportsOpen ? "rotate-180 text-white" : "text-[#333333]"
                      }`}
                    />
                  )}
                </button>
                {isReportsOpen && (
                  <ul className={`mt-1 space-y-1 ${isCollapsed ? "pl-0" : "pl-4"}`}>
                    {ReportItems.map((item) => {
                      const isActive = location.pathname === item.href
                      return (
                        <li key={item.title}>
                          <button
                            onClick={() => navigate(item.href)}
                            className={`flex items-center w-full rounded-md px-3 py-2.5 text-sm font-medium transition-all ${
                              isActive
                                ? "bg-[#C8A45D]/20 text-[#00717F] shadow-sm"
                                : "text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F]"
                            }`}
                          >
                            <item.icon className={`h-5 w-5 ${isActive ? "text-[#00717F]" : "text-[#333333]"}`} />
                            {!isCollapsed && (
                              <span className="ml-3 truncate transition-opacity duration-200">{item.title}</span>
                            )}
                          </button>
                        </li>
                      )
                    })}
                  </ul>
                )}
              </li>
            </ul>
          </nav>

          <div className="mt-auto border-t border-[#C8A45D]/30 px-2 py-4">
            <ul className="space-y-1">
              {bottomNavItems.map((item) => (
                <li key={item.title}>
                  <button
                    onClick={() => navigate(item.href)}
                    className="flex items-center w-full rounded-md px-3 py-2.5 text-sm font-medium text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F] transition-all"
                  >
                    <item.icon className="h-5 w-5 text-[#333333]" />
                    {!isCollapsed && <span className="ml-3 transition-opacity duration-200">{item.title}</span>}
                  </button>
                </li>
              ))}
              <li>
                <button
                  onClick={handleLogout}
                  className="flex items-center w-full rounded-md px-3 py-2.5 text-sm font-medium text-[#333333] hover:bg-red-50 hover:text-red-600 transition-all"
                >
                  <LogOut className="h-5 w-5 text-[#333333]" />
                  {!isCollapsed && <span className="ml-3 transition-opacity duration-200">Déconnexion</span>}
                </button>
              </li>
            </ul>
          </div>
        </div>
      </div>

      {!isCollapsed && isMobile && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-40 backdrop-blur-sm transition-all duration-300"
          onClick={() => setIsCollapsed(true)}
        />
      )}
    </>
  )
}
